    $new = $new.Replace("`r`n","`n").Replace('NAME_OUTPUT',($name+'Output')).Replace('ENVNAME',$envName).Replace('LABEL',$label).Replace('SUFFIX',$suffix)
    if ([regex]::Matches($candidate,[regex]::Escape($old)).Count -ne 1) { throw "Original $name write boundary mismatch" }
    $candidate = $candidate.Replace($old,$new)
  }
  if ([Text.Encoding]::UTF8.GetByteCount($candidate) -ne 9328 -or (Get-TextHash $candidate) -cne $actionHash) { throw 'Candidate action bytes mismatch' }
  $null = Get-ParsedSource $candidate
  $helper = Join-Path ([IO.Path]::GetDirectoryName($action)) 'DuplicateFunctionCheck.Paths.ps1'
  [IO.File]::WriteAllText($action,$candidate,$utf8)
  [IO.File]::WriteAllText($helper,$helperText,$utf8)
  if ((Get-FileHash -LiteralPath $action -Algorithm SHA256).Hash.ToLowerInvariant() -cne $actionHash -or (Get-FileHash -LiteralPath $helper -Algorithm SHA256).Hash.ToLowerInvariant() -cne $helperHash) { throw 'Written candidate hash mismatch' }
  Write-Output "CANDIDATE_VERIFIED action_sha256=$actionHash helper_sha256=$helperHash tracked=47 pwsh=$($PSVersionTable.PSVersion)"
  Set-Location -LiteralPath $repo
  $pwsh = (Get-Process -Id $PID).Path
  $json = Join-Path $repo 'project_sources/collector/powershell_duplicate_function_report.json'
  $markdown = Join-Path $repo 'project_sources/collector/powershell_duplicate_function_report.md'
  if ([IO.File]::Exists($json) -or [IO.File]::Exists($markdown)) { throw 'Unexpected preexisting report' }
  $collector = Join-Path $repo 'project_sources/collector'
  $outside = Join-Path $scratch 'outside'
  $null = [IO.Directory]::CreateDirectory($outside)
  $outsideJson = Join-Path $outside 'report.json'
  $outsideMarkdown = Join-Path $outside 'report.md'
  [IO.File]::WriteAllText($outsideJson,'outside-json-sentinel',$utf8)
  [IO.File]::WriteAllText($outsideMarkdown,'outside-md-sentinel',$utf8)
  $link = Join-Path $collector 'link'
  $null = New-Item -ItemType Junction -Path $link -Target $outside -ErrorAction Stop
  $item = Get-Item -LiteralPath $link -Force -ErrorAction Stop
  if ($item.LinkType -ne 'Junction' -or [string](@($item.Target)[0]) -cne $outside -or ($item.Attributes -band [IO.FileAttributes]::ReparsePoint) -eq 0) { throw 'Junction fixture mismatch' }
  foreach ($polarity in @('hostile-json','hostile-markdown')) {
    $env:DUPLICATE_FUNCTION_OUTPUT_JSON = 'project_sources/collector/safe-pair/report.json'
    $env:DUPLICATE_FUNCTION_OUTPUT_MARKDOWN = 'project_sources/collector/safe-pair/report.md'
    if ($polarity -eq 'hostile-json') { $env:DUPLICATE_FUNCTION_OUTPUT_JSON = 'project_sources/collector/link/report.json' }
    else { $env:DUPLICATE_FUNCTION_OUTPUT_MARKDOWN = 'project_sources/collector/link/report.md' }
    $output = @(& $pwsh -NoProfile -NonInteractive -File $action 2>&1)
    $exit = $LASTEXITCODE
    $message = $output -join "`n"
    if ($exit -eq 0 -or $message -notmatch 'reparse point') { throw "Hostile output was not rejected: $polarity $message" }
    if ([IO.Directory]::Exists((Join-Path $collector 'safe-pair')) -or [IO.File]::Exists($json) -or [IO.File]::Exists($markdown) -or [IO.File]::ReadAllText($outsideJson) -cne 'outside-json-sentinel' -or [IO.File]::ReadAllText($outsideMarkdown) -cne 'outside-md-sentinel' -or @(Get-ChildItem -LiteralPath $outside -Force).Count -ne 2) { throw "Unexpected write before rejection: $polarity" }
    Write-Output "ACTION_REJECTION_PASS case=$polarity exit=$exit"
  }
  [IO.Directory]::Delete($link,$false)
  try { $null = [IO.File]::GetAttributes($link); throw 'Junction cleanup failed' }
  catch [IO.FileNotFoundException] { }
  catch [IO.DirectoryNotFoundException] { }
  $link = $null
  $existing = Join-Path $collector 'existing'
