  $env:DUPLICATE_FUNCTION_OUTPUT_JSON = 'project_sources/collector/existing/report.json'
  $env:DUPLICATE_FUNCTION_OUTPUT_MARKDOWN = 'project_sources/collector/literal [x]/nested/report.md'
  $literalMd = Join-Path $repo $env:DUPLICATE_FUNCTION_OUTPUT_MARKDOWN
  $output = @(& $pwsh -NoProfile -NonInteractive -File $action 2>&1)
  $exit = $LASTEXITCODE
  if ($exit -ne 0 -or -not [IO.File]::Exists($literalMd)) { throw "Legitimate output failed: $($output -join ' ')" }
  $report = [IO.File]::ReadAllText($existingJson) | ConvertFrom-Json
  if (-not $report.validation.success -or $report.summary.file_count -ne 45 -or $report.summary.duplicate_function_count -ne 0 -or $report.artifact_contract.local_artifacts.json -cne $env:DUPLICATE_FUNCTION_OUTPUT_JSON -or $report.artifact_contract.local_artifacts.markdown -cne $env:DUPLICATE_FUNCTION_OUTPUT_MARKDOWN -or -not [IO.File]::ReadAllText($literalMd).Contains($env:DUPLICATE_FUNCTION_OUTPUT_MARKDOWN)) { throw 'Legitimate output contract mismatch' }
  if ([IO.Directory]::Exists((Join-Path $collector 'literal x')) -or [IO.File]::ReadAllText($outsideJson) -cne 'outside-json-sentinel' -or [IO.File]::ReadAllText($outsideMarkdown) -cne 'outside-md-sentinel') { throw 'Unexpected legitimate output side effect' }
  Write-Output 'ACTION_SAFE_WRITE_PASS existing=1 literal_bracket=1'
  $packed = [IO.MemoryStream]::new()
  try {
    $gzip = [IO.Compression.GZipStream]::new($packed,[IO.Compression.CompressionMode]::Compress,$true)
    try { $data = $utf8.GetBytes($candidate); $gzip.Write($data,0,$data.Length) } finally { $gzip.Dispose() }
    Write-Output "CANDIDATE_ACTION_GZIP_BASE64 data=$([Convert]::ToBase64String($packed.ToArray()))"
  } finally { $packed.Dispose() }
  Write-Output 'NATIVE_ACTION_INTEGRATION_COMPLETE hostile=2 safe=2'
} finally {
  Set-Location -LiteralPath $start
  [Environment]::SetEnvironmentVariable('DUPLICATE_FUNCTION_OUTPUT_JSON',$oldJson,'Process')
  [Environment]::SetEnvironmentVariable('DUPLICATE_FUNCTION_OUTPUT_MARKDOWN',$oldMarkdown,'Process')
  if ($owned) {
    if ($null -ne $link) {
      $attrs = $null
      try { $attrs = [IO.File]::GetAttributes($link) }
      catch [IO.FileNotFoundException] { }
      catch [IO.DirectoryNotFoundException] { }
      if ($null -ne $attrs) {
        if (($attrs -band [IO.FileAttributes]::ReparsePoint) -eq 0 -or ($attrs -band [IO.FileAttributes]::Directory) -eq 0) { throw 'Unsafe alias cleanup; retaining scratch' }
        [IO.Directory]::Delete($link,$false)
      }
      try { $null = [IO.File]::GetAttributes($link); throw 'Alias cleanup failed; retaining scratch' }
      catch [IO.FileNotFoundException] { }
      catch [IO.DirectoryNotFoundException] { }
    }
    Remove-Item -LiteralPath $scratch -Recurse -Force -ErrorAction Stop
  }
}
